{
  "product": {
    "title": "Mobile App Demo Product",
    "body_html": "<strong>Demo product created from Postman.</strong>",
    "vendor": "{{vendor}}",
    "product_type": "{{product_type}}",
    "status": "draft",
    "tags": "mobile-app,demo",
    "options": [
      {
        "name": "Color",
        "values": [
          "Black",
          "White"
        ]
      }
    ],
    "variants": [
      {
        "option1": "Black",
        "price": "19.99",
        "sku": "MOBILE-DEMO-BLK",
        "inventory_management": "shopify"
      },
      {
        "option1": "White",
        "price": "19.99",
        "sku": "MOBILE-DEMO-WHT",
        "inventory_management": "shopify"
      }
    ]
  }
}

{
  "custom_collection": {
    "title": "Mobile App Manual Category",
    "body_html": "<p>Manual category for the mobile app.</p>",
    "published": false
  }
}

{
  "order": {
    "line_items": [
      {
        "variant_id": "{{variant_id}}",
        "quantity": 1
      }
    ],
    "customer": {
      "id": "{{customer_id}}"
    },
    "financial_status": "pending",
    "send_receipt": true,
    "inventory_behaviour": "decrement_obeying_policy",
    "note": "Created from mobile app Admin REST Postman collection."
  }
}

{
  "draft_order_invoice": {
    "to": "{{customer_email}}",
    "from": "{{shop_owner_email}}",
    "subject": "Invoice for your order",
    "custom_message": "Please review your invoice."
  }
}

{
  "order": {
    "line_items": [
      {
        "variant_id": "{{variant_id}}",
        "quantity": 1
      }
    ],
    "customer": {
      "id": "{{customer_id}}"
    },
    "financial_status": "pending",
    "send_receipt": true,
    "inventory_behaviour": "decrement_obeying_policy",
    "note": "Created from mobile app Admin REST Postman collection."
  }
}
